export const ALL=[...STRUCTURES,...Object.values(EXTERNAL),...METHODS];
export const BY_ID=Object.fromEntries(ALL.map(s=>[s.id,s]));
// Explicit examples for concepts that are not a single segmented structure.
// Unrepresented nerves and spinal cord never borrow another structure's mesh.
export const DISPLAY_REFERENCES={
 emotion:{names:['lh_hippocampus','rh_hippocampus','lh_amygdala','rh_amygdala'],label:'Hippocampes et amygdales · exemples du réseau'},
 tractography:{id:'callosum',label:'Corps calleux · exemple de faisceau'},
 fmri:{id:'m1',label:'M1 · exemple pour une tâche motrice'},
 tms:{id:'m1',label:'M1 · exemple de stimulation'},
};
export function displayMatches(s,m){
 const reference=DISPLAY_REFERENCES[s.id];
 if(reference?.id)return matches(BY_ID[reference.id],m);
 if(reference?.names)return reference.names.includes(m.name);
 return matches(s,m);
}
