export function lobeFor(p){
 if(/Ins|insul/.test(p))return 'insula';
 if(/occipital|occip|calcarine|cuneus|Lingual|oc_middle|oc_sup/.test(p)&&!p.includes('precuneus')&&!p.includes('parieto'))return 'occipital';
 if(/temporal|temp_|temp-|Pole_temporal|fusifor|Parahip|collat/.test(p))return 'temporal';
 if(/postcentral|pariet|precuneus|Angular|Supramar|Jensen|subpariet/.test(p))return 'parietal';
 if(/front|precentral|orbital|rectus|subcallosal|paracentral|subcentral|cingul-Ant|cingul-Mid-Ant/.test(p))return 'frontal';
 return 'neutral';
}
export function matches(s,m){
 const p=m.label;
 if(s.hemi&&s.hemi!==m.hemi)return false;
 if(s.type==='allCortex')return m.kind==='cortex';
 if(s.type==='lobe')return m.kind==='cortex'&&lobeFor(p)===s.lobe;
 if(s.type==='parcel')return s.parcels.includes(p);
 if(s.type==='sulci')return m.kind==='cortex'&&(/^(S_|Lat_Fis)/.test(p));
 if(s.type==='gyri')return m.kind==='cortex'&&p.startsWith('G_');
 if(s.type==='grey')return m.kind==='cortex'||p.includes('thalamus');
 if(s.type==='association')return ['G_front_middle','G_front_sup','G_pariet_inf-Angular','G_pariet_inf-Supramar','G_temporal_inf','G_temporal_middle'].includes(p);
 return s.names?.some(n=>m.name===n)||false;
}
